// ===== GitHub-backed storage (shared by both sites). All data lives as JSON files in your PRIVATE GitHub repo. =====
class HttpErr extends Error { constructor(status, msg) { super(msg); this.status = status; } }
const GH_API = 'https://api.github.com';
const b64enc = (str) => { const b = new TextEncoder().encode(str); let s = ''; for (let i = 0; i < b.length; i += 0x8000) s += String.fromCharCode(...b.subarray(i, i + 0x8000)); return btoa(s); };
const b64dec = (s) => new TextDecoder().decode(Uint8Array.from(atob(s.replace(/\s/g, '')), (c) => c.charCodeAt(0)));
function ghHeaders(env, extra) {
  if (!env.GH_TOKEN || !env.GH_REPO) throw new HttpErr(500, 'Storage is not connected yet: set GH_TOKEN and GH_REPO in Cloudflare.');
  return { authorization: `Bearer ${env.GH_TOKEN}`, 'user-agent': 'dinesh-site', accept: 'application/vnd.github+json', 'x-github-api-version': '2022-11-28', ...extra };
}
const ghBranch = (env) => env.GH_BRANCH || 'main';
async function ghGet(env, path) {
  const r = await fetch(`${GH_API}/repos/${env.GH_REPO}/contents/${path}?ref=${ghBranch(env)}`, { headers: ghHeaders(env) });
  if (r.status === 404) return null;
  if (!r.ok) throw new HttpErr(502, `GitHub ${r.status}: could not read ${path} (check GH_TOKEN / GH_REPO).`);
  const j = await r.json();
  let content = j.content;
  if (!content) { const b = await fetch(`${GH_API}/repos/${env.GH_REPO}/git/blobs/${j.sha}`, { headers: ghHeaders(env) }); content = (await b.json()).content; }
  return { text: b64dec(content), sha: j.sha };
}
async function ghPut(env, path, b64, sha, msg) {
  const r = await fetch(`${GH_API}/repos/${env.GH_REPO}/contents/${path}`, { method: 'PUT', headers: ghHeaders(env, { 'content-type': 'application/json' }), body: JSON.stringify({ message: msg, content: b64, branch: ghBranch(env), ...(sha ? { sha } : {}) }) });
  if (r.ok) return (await r.json()).content.sha;
  if (r.status === 409 || r.status === 422) return 'CONFLICT';
  const e = await r.json().catch(() => ({}));
  throw new HttpErr(502, `GitHub ${r.status}: ${r.status === 401 ? 'GH_TOKEN is wrong or expired.' : r.status === 404 ? 'Repo not found or token has no access (check GH_REPO and token permissions).' : e.message || 'error'}`);
}
const DEFAULT_SETTINGS = { about_name: 'Dinesh Rajbanshi', about_title: 'Modern farming educator & developer', about_bio: 'Write about yourself from the admin site > Profile.', about_photo: '', contact_email: 'dinesh.fm@gmail.com', contact_phone: '', contact_video: '', site_tagline: 'Practical knowledge for the modern farmer', pay_info: 'We will contact you on your phone to confirm your seat and share payment details.' };
function defaults(name) {
  if (name === 'settings') return { ...DEFAULT_SETTINGS };
  if (name === 'articles') {
    const t = Date.now();
    return { next_id: 2, items: [{ id: 1, title: 'Welcome to my website', subtitle: 'Articles, online classes and a community for farmers who want to grow smarter.', category: 'Announcement', body: 'This is a sample article so your site is not empty. Delete or edit it from the admin site.\n\n## What you will find here\n\n- Professional articles on crops, soil, water and technology\n- Online classes you can book in a minute\n- A discussion space where every farmer can ask and answer\n\n> Good farming is a conversation between people, soil and season.', highlights: 'Read and listen to every article\nBook online classes\nAsk the community', img1: '', img1_cap: '', img2: '', img2_cap: '', video: '', lang: 'en-US', author: 'Dinesh Rajbanshi', published: 1, created_at: t, updated_at: t }] };
  }
  return { next_id: 1, items: [] };
}
const STORE = new Map(); let STORE_TTL = 15000;
async function loadFile(env, name, fresh) {
  const c = STORE.get(name);
  if (!fresh && c && Date.now() - c.t < STORE_TTL) return c;
  const f = await ghGet(env, `data/${name}.json`);
  const e = { t: Date.now(), sha: f ? f.sha : null, data: f ? JSON.parse(f.text) : defaults(name) };
  STORE.set(name, e); return e;
}
const readData = async (env, name, fresh) => (await loadFile(env, name, fresh)).data;
// Safe read-modify-write: if two people save at the same moment, GitHub rejects the second and we re-apply on fresh data.
async function mutate(env, name, fn) {
  for (let i = 0; i < 6; i++) {
    const e = await loadFile(env, name, true);
    const data = structuredClone(e.data);
    const out = await fn(data);
    const sha = await ghPut(env, `data/${name}.json`, b64enc(JSON.stringify(data)), e.sha, 'Update ' + name);
    if (sha !== 'CONFLICT') { STORE.set(name, { t: Date.now(), sha, data }); return out; }
    STORE.delete(name);
    await new Promise((r) => setTimeout(r, 80 + Math.random() * 200));
  }
  throw new HttpErr(503, 'The site is busy. Please try again in a moment.');
}
const HITS = new Map();
function tooFast(key, max, windowMs) {
  const now = Date.now(), arr = (HITS.get(key) || []).filter((t) => now - t < windowMs);
  if (arr.length >= max) { HITS.set(key, arr); return true; }
  arr.push(now); HITS.set(key, arr);
  if (HITS.size > 5000) HITS.clear();
  return false;
}
async function ghImage(env, p, ttl) {
  const path = p.slice(5);
  if (!/^[\w\-\/.]+$/.test(path) || path.includes('..')) return new Response('Not found', { status: 404 });
  const r = await fetch(`${GH_API}/repos/${env.GH_REPO}/contents/img/${path}?ref=${ghBranch(env)}`, { headers: ghHeaders(env, { accept: 'application/vnd.github.raw+json' }), cf: { cacheEverything: true, cacheTtl: ttl } });
  if (!r.ok) return new Response('Not found', { status: 404 });
  const type = /\.png$/i.test(path) ? 'image/png' : /\.webp$/i.test(path) ? 'image/webp' : 'image/jpeg';
  return new Response(r.body, { headers: { 'content-type': type, 'cache-control': `public, max-age=${ttl}`, 'x-content-type-options': 'nosniff' } });
}
const errResponse = (J, e) => (e instanceof HttpErr ? J({ error: e.message }, e.status) : J({ error: 'Server error. Please try again.' }, 500));
// ===== end storage =====

// Public website worker (Cloudflare Pages advanced mode). No database: everything is stored in your private GitHub repo.
// Needs: GH_TOKEN (secret), GH_REPO ("username/farming-data"); optional GH_BRANCH.

const J = (d, s = 200, h = {}) =>
  new Response(JSON.stringify(d), {
    status: s,
    headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', 'x-content-type-options': 'nosniff', ...h },
  });
const clip = (v, n) => String(v ?? '').replace(/\u0000/g, '').trim().slice(0, n);
const now = () => Date.now();
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const PUBLIC_KEYS = ['about_name', 'about_title', 'about_bio', 'about_photo', 'contact_email', 'contact_phone', 'contact_video', 'site_tagline'];
const ip = (req) => req.headers.get('CF-Connecting-IP') || 'local';
const body = async (req) => { try { return await req.json(); } catch { return {}; } };
const brief = (a) => ({ id: a.id, title: a.title, subtitle: a.subtitle, category: a.category, img1: a.img1, author: a.author, created_at: a.created_at, len: (a.body || '').length });
const byNew = (a, b) => b.created_at - a.created_at;

const __worker = {
  async fetch(req, env) {
    const url = new URL(req.url);
    const p = url.pathname;
    try {
      if (p.startsWith('/api/')) return await api(req, env, p, url);
      if (p.startsWith('/img/')) return await ghImage(env, p, 31536000);
      const m = p.match(/^\/article\/(\d+)\/?$/);
      if (m) return await articlePage(env, url, Number(m[1]));
      return env.ASSETS.fetch(req);
    } catch (e) {
      return errResponse(J, e);
    }
  },
};

async function api(req, env, p, url) {
  const method = req.method;

  if (method === 'GET' && p === '/api/stats') {
    const [a, c, po] = await Promise.all([readData(env, 'articles'), readData(env, 'classes'), readData(env, 'posts')]);
    return J({ articles: a.items.filter((x) => x.published).length, classes: c.items.filter((x) => x.active).length, posts: po.items.length });
  }

  if (method === 'GET' && p === '/api/feed') {
    const [a, c] = await Promise.all([readData(env, 'articles'), readData(env, 'classes')]);
    const list = [
      ...a.items.filter((x) => x.published).map((x) => ({ type: 'article', id: x.id, title: x.title, summary: x.subtitle || '', image: x.img1, tag: x.category, price: null, currency: null, created_at: x.created_at })),
      ...c.items.filter((x) => x.active).map((x) => ({ type: 'class', id: x.id, title: x.title, summary: x.description || '', image: x.img, tag: x.mode, price: x.price, currency: x.currency, created_at: x.created_at })),
    ].sort(byNew).slice(0, 60);
    return J(list);
  }

  if (method === 'GET' && p === '/api/articles') {
    const lim = Math.min(Number(url.searchParams.get('limit')) || 12, 50);
    const off = Math.max(Number(url.searchParams.get('offset')) || 0, 0);
    const cat = clip(url.searchParams.get('category'), 60);
    const all = (await readData(env, 'articles')).items.filter((x) => x.published).sort(byNew);
    const counts = {};
    for (const x of all) counts[x.category] = (counts[x.category] || 0) + 1;
    const categories = Object.entries(counts).map(([category, n]) => ({ category, n })).sort((a, b) => b.n - a.n);
    const items = all.filter((x) => !cat || x.category === cat).slice(off, off + lim).map(brief);
    return J({ items, categories });
  }

  let m = p.match(/^\/api\/articles\/(\d+)$/);
  if (method === 'GET' && m) {
    let all = (await readData(env, 'articles')).items.filter((x) => x.published).sort(byNew);
    let a = all.find((x) => x.id === Number(m[1]));
    if (!a) { all = (await readData(env, 'articles', true)).items.filter((x) => x.published).sort(byNew); a = all.find((x) => x.id === Number(m[1])); }
    if (!a) return J({ error: 'Article not found' }, 404);
    return J({ article: a, more: all.filter((x) => x.id !== a.id).slice(0, 3).map(brief) });
  }

  if (method === 'GET' && p === '/api/posts') {
    const lim = Math.min(Number(url.searchParams.get('limit')) || 40, 100);
    const items = (await readData(env, 'posts')).items;
    const tops = items.filter((x) => !x.parent_id).sort(byNew).slice(0, lim).map((t) => ({ id: t.id, name: t.name, message: t.message, created_at: t.created_at, replies: [] }));
    const idx = new Map(tops.map((t) => [t.id, t]));
    for (const r of items.filter((x) => x.parent_id).sort((a, b) => a.created_at - b.created_at)) idx.get(r.parent_id)?.replies.push({ id: r.id, parent_id: r.parent_id, name: r.name, message: r.message, created_at: r.created_at });
    return J(tops);
  }

  if (method === 'POST' && p === '/api/posts') {
    const b = await body(req);
    if (b.website) return J({ ok: true });
    const name = clip(b.name, 40), message = clip(b.message, 1500), pid = b.parent_id ? Number(b.parent_id) : null;
    if (name.length < 2) return J({ error: 'Please enter your name.' }, 400);
    if (message.length < 3) return J({ error: 'Please write a message.' }, 400);
    if (tooFast('post' + ip(req), 4, 60000)) return J({ error: 'Slow down a little and try again in a minute.' }, 429);
    const t = now();
    const id = await mutate(env, 'posts', (d) => {
      if (pid && !d.items.some((x) => x.id === pid && !x.parent_id)) throw new HttpErr(404, 'Discussion not found.');
      const nid = d.next_id++;
      d.items.push({ id: nid, parent_id: pid, name, message, created_at: t });
      return nid;
    });
    return J({ id, parent_id: pid, name, message, created_at: t, replies: [] }, 201);
  }

  if (method === 'GET' && p === '/api/classes') {
    const [c, b] = await Promise.all([readData(env, 'classes'), readData(env, 'bookings')]);
    const booked = {};
    for (const x of b.items) if (x.status !== 'cancelled') booked[x.class_id] = (booked[x.class_id] || 0) + 1;
    return J(c.items.filter((x) => x.active).sort(byNew).map((x) => ({ id: x.id, title: x.title, description: x.description, price: x.price, currency: x.currency, schedule: x.schedule, duration: x.duration, mode: x.mode, seats: x.seats, img: x.img, created_at: x.created_at, booked: booked[x.id] || 0 })));
  }

  if (method === 'POST' && p === '/api/bookings') {
    const b = await body(req);
    if (b.website) return J({ ok: true });
    const name = clip(b.name, 80), phone = clip(b.phone, 30), email = clip(b.email, 120), note = clip(b.note, 500);
    if (name.length < 2) return J({ error: 'Please enter your name.' }, 400);
    if (phone.replace(/\D/g, '').length < 7) return J({ error: 'Please enter a valid phone / WhatsApp number.' }, 400);
    if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return J({ error: 'That email looks wrong.' }, 400);
    const findCl = (d) => d.items.find((x) => x.id === Number(b.class_id) && x.active);
    const cl = findCl(await readData(env, 'classes')) || findCl(await readData(env, 'classes', true));
    if (!cl) return J({ error: 'This class is no longer available.' }, 404);
    if (tooFast('book' + ip(req), 5, 600000)) return J({ error: 'Too many bookings from your connection. Try later.' }, 429);
    await mutate(env, 'bookings', (d) => {
      if (cl.seats > 0 && d.items.filter((x) => x.class_id === cl.id && x.status !== 'cancelled').length >= cl.seats) throw new HttpErr(409, 'Sorry, this class is full.');
      d.items.push({ id: d.next_id++, class_id: cl.id, name, email, phone, note, status: 'pending', created_at: now() });
    });
    const s = await readData(env, 'settings');
    return J({ ok: true, title: cl.title, pay_info: s.pay_info || '' }, 201);
  }

  if (method === 'GET' && p === '/api/settings') {
    const s = await readData(env, 'settings'), out = {};
    for (const k of PUBLIC_KEYS) out[k] = s[k] ?? '';
    return J(out, 200, { 'cache-control': 'public, max-age=30' });
  }

  if (method === 'POST' && p === '/api/contact') {
    const b = await body(req);
    if (b.website) return J({ ok: true });
    const name = clip(b.name, 80), email = clip(b.email, 120), message = clip(b.message, 3000);
    if (name.length < 2 || message.length < 5) return J({ error: 'Please fill in your name and message.' }, 400);
    if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) return J({ error: 'That email looks wrong.' }, 400);
    if (tooFast('msg' + ip(req), 3, 600000)) return J({ error: 'Too many messages. Please try later.' }, 429);
    await mutate(env, 'messages', (d) => { d.items.push({ id: d.next_id++, name, email, message, is_read: 0, created_at: now() }); });
    return J({ ok: true }, 201);
  }

  return J({ error: 'Not found' }, 404);
}

// Article pages get real <title>/Open Graph tags so WhatsApp/Facebook previews look professional.
async function articlePage(env, url, id) {
  const shell = await env.ASSETS.fetch(new Request(new URL('/', url).toString()));
  let html = await shell.text();
  let a = null;
  try { const f = (d) => d.items.find((x) => x.id === id && x.published); a = f(await readData(env, 'articles')) || f(await readData(env, 'articles', true)); } catch {}
  if (a) {
    const title = `${a.title} | Dinesh Rajbanshi`;
    const desc = a.subtitle || 'Read this article on Dinesh Rajbanshi.';
    const img = a.img1 ? new URL(a.img1, url).href : '';
    const tags =
      `<meta name="description" content="${esc(desc)}">` +
      `<meta property="og:type" content="article"><meta property="og:title" content="${esc(a.title)}">` +
      `<meta property="og:description" content="${esc(desc)}"><meta property="og:url" content="${esc(url.href)}">` +
      (img ? `<meta property="og:image" content="${esc(img)}"><meta name="twitter:card" content="summary_large_image">` : '');
    html = html.replace(/<title>[\s\S]*?<\/title>/, `<title>${esc(title)}</title>`).replace('</head>', tags + '</head>');
  }
  return new Response(html, { headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'public, max-age=60' } });
}

